def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries (for LRU consideration)
            expired_keys = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
            for k in expired_keys:
                del cache[k]

            # If key exists, remove it to re-insert at end (most recent)
            if key in cache:
                del cache[key]
            # If cache is at capacity, evict least recently used
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Insert the new entry
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Check if key exists and is not expired
            if key in cache:
                value, write_time = cache[key]
                if write_time + ttl > t:
                    # Entry is valid, make it most recently used
                    del cache[key]
                    cache[key] = (value, write_time)
                    results.append(value)
                else:
                    # Entry is expired
                    del cache[key]
                    results.append(-1)
            else:
                results.append(-1)

    return results

